/**
 * Toast's states fixture, with the React fixture's entry names, so a
 * contract's `when <state>` names the same entry in both shells.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/toast.ts`. Never edit it by hand.
 */
import { h } from 'vue'

import { TOAST_MAX_VISIBLE, toast, type ComponentStates } from '@polymorph/vue'

import Button from '../controls/Button.vue'
import Inline from '../layout/Inline.vue'
import Toast from './Toast.vue'
import ToastViewport from './ToastViewport.vue'

export const states: ComponentStates = {
  component: 'Toast',
  entries: [
    {
      name: 'the viewport, with a pinned title, a description and an action',
      render: (overrides = {}) =>
        h({
          setup() {
            return () => [
              h(Toast, {
                title: 'Ticket archived',
                tone: 'success',
                action: {
                  label: 'Undo',
                  onClick: () =>
                    document.dispatchEvent(
                      new CustomEvent('polymorph:fixturecall', { detail: 'onClick' }),
                    ),
                },
                onDismiss: () =>
                  document.dispatchEvent(
                    new CustomEvent('polymorph:fixturecall', { detail: 'onDismiss' }),
                  ),
                durationMs: Number.POSITIVE_INFINITY,
              }),
              h(Toast, {
                title: 'Ticket created',
                onDismiss: () =>
                  document.dispatchEvent(
                    new CustomEvent('polymorph:fixturecall', { detail: 'onDismiss' }),
                  ),
                durationMs: Number.POSITIVE_INFINITY,
              }),
              h(Toast, {
                title: 'Ticket assigned',
                description: 'Sent to the triage queue.',
                onDismiss: () =>
                  document.dispatchEvent(
                    new CustomEvent('polymorph:fixturecall', { detail: 'onDismiss' }),
                  ),
                durationMs: Number.POSITIVE_INFINITY,
              }),
              h(ToastViewport, { ...overrides }),
            ]
          },
        }),
    },
    {
      name: 'every tone — the card is the same, the glyph is not',
      render: () =>
        h(
          Inline,
          { gap: 2, wrap: true },
          {
            default: () => [
              h(Button, {
                variant: 'outline',
                tone: 'neutral',
                size: 'sm',
                label: 'neutral',
                onClick: () =>
                  toast({
                    title: 'Neutral',
                    description: 'The tone speaks through the glyph and nothing else.',
                    tone: 'neutral',
                  }),
              }),
              h(Button, {
                variant: 'outline',
                tone: 'neutral',
                size: 'sm',
                label: 'success',
                onClick: () =>
                  toast({
                    title: 'Success',
                    description: 'The tone speaks through the glyph and nothing else.',
                    tone: 'success',
                  }),
              }),
              h(Button, {
                variant: 'outline',
                tone: 'neutral',
                size: 'sm',
                label: 'danger',
                onClick: () =>
                  toast({
                    title: 'Danger',
                    description: 'The tone speaks through the glyph and nothing else.',
                    tone: 'danger',
                  }),
              }),
              h(Button, {
                variant: 'outline',
                tone: 'neutral',
                size: 'sm',
                label: 'warning',
                onClick: () =>
                  toast({
                    title: 'Warning',
                    description: 'The tone speaks through the glyph and nothing else.',
                    tone: 'warning',
                  }),
              }),
              h(Button, {
                variant: 'outline',
                tone: 'neutral',
                size: 'sm',
                label: 'info',
                onClick: () =>
                  toast({
                    title: 'Info',
                    description: 'The tone speaks through the glyph and nothing else.',
                    tone: 'info',
                  }),
              }),
            ],
          },
        ),
    },
    {
      name: 'with an action',
      render: () =>
        h(
          Inline,
          { gap: 2, wrap: true },
          {
            default: () => [
              h(Button, {
                variant: 'outline',
                tone: 'neutral',
                size: 'sm',
                label: 'Archive a ticket',
                onClick: () =>
                  toast.success('Ticket archived', {
                    action: { label: 'Undo', onClick: () => undefined },
                  }),
              }),
              h(Button, {
                variant: 'outline',
                tone: 'neutral',
                size: 'sm',
                label: 'Fail to delete one',
                onClick: () =>
                  toast.danger('Could not delete', {
                    description: 'The ticket is referenced by another.',
                    action: { label: 'Retry', onClick: () => undefined },
                  }),
              }),
            ],
          },
        ),
    },
    {
      name: 'pinned — it waits to be dismissed',
      render: () =>
        h(
          Inline,
          { gap: 2, wrap: true },
          {
            default: () => [
              h(Button, {
                variant: 'outline',
                tone: 'neutral',
                size: 'sm',
                label: 'Raise a pinned toast',
                onClick: () =>
                  toast({
                    title: 'Still working',
                    description: 'This one has no timer.',
                    durationMs: Number.POSITIVE_INFINITY,
                  }),
              }),
            ],
          },
        ),
    },
    {
      name: 'a promise — the loading face pinned, then the settled face, same card',
      render: () =>
        h(
          Inline,
          { gap: 2, wrap: true },
          {
            default: () => [
              h(Button, {
                variant: 'outline',
                tone: 'neutral',
                size: 'sm',
                label: 'Archive, resolving',
                onClick: () =>
                  toast.promise(new Promise((resolve) => setTimeout(resolve, 2500)), {
                    loading: 'Archiving ticket…',
                    success: 'Ticket archived',
                    error: 'Could not archive',
                  }),
              }),
              h(Button, {
                variant: 'outline',
                tone: 'neutral',
                size: 'sm',
                label: 'Archive, failing',
                onClick: () =>
                  toast.promise(new Promise((_, reject) => setTimeout(reject, 2500)), {
                    loading: 'Archiving ticket…',
                    success: 'Ticket archived',
                    error: { title: 'Could not archive', description: 'The queue is read-only.' },
                  }),
              }),
            ],
          },
        ),
    },
    {
      name: 'updated in place — a second call with the first’s id, one card',
      render: () =>
        h(
          Inline,
          { gap: 2, wrap: true },
          {
            default: () => [
              h(Button, {
                variant: 'outline',
                tone: 'neutral',
                size: 'sm',
                label: 'Raise, then update it',
                onClick: () => {
                  toast({
                    id: 'update-demo',
                    title: 'Exporting 0 of 3…',
                    durationMs: Number.POSITIVE_INFINITY,
                  })
                  setTimeout(
                    () =>
                      toast({
                        id: 'update-demo',
                        title: 'Exporting 2 of 3…',
                        durationMs: Number.POSITIVE_INFINITY,
                      }),
                    1200,
                  )
                  setTimeout(
                    () => toast({ id: 'update-demo', title: 'Export ready', tone: 'success' }),
                    2400,
                  )
                },
              }),
            ],
          },
        ),
    },
    {
      name: 'a stack — the survivors glide into the gap',
      render: () =>
        h(
          Inline,
          { gap: 2, wrap: true },
          {
            default: () => [
              h(Button, {
                variant: 'outline',
                tone: 'neutral',
                size: 'sm',
                label: 'Raise 4',
                onClick: () => {
                  for (let index = 1; index <= TOAST_MAX_VISIBLE; index += 1)
                    toast({ title: `Toast ${index}`, durationMs: Number.POSITIVE_INFINITY })
                },
              }),
              h(Button, {
                variant: 'outline',
                tone: 'neutral',
                size: 'sm',
                label: 'Raise more than it will keep',
                onClick: () => {
                  for (let index = 1; index <= TOAST_MAX_VISIBLE + 3; index += 1)
                    toast({ title: `Overflow ${index}` })
                },
              }),
              h(Button, {
                variant: 'ghost',
                tone: 'danger',
                size: 'sm',
                label: 'Dismiss all',
                onClick: () => toast.dismiss(),
              }),
            ],
          },
        ),
    },
  ],
}
